rm -rf "$probe"
case "$rc" in
  0|3) status proxy_ok; printf '%s\n' "$proxy" > "$work/proxy-url"; exit 0 ;;
  4) status proxy_429; stop; exit 4 ;;
  *) status proxy_error; stop; exit 2 ;;
